// OpenCode plugin from @blit386/kit (generated by `npx blit agents sync`; your edits are flagged on sync).
//
// OpenCode runs every file in .opencode/plugins/ the moment it opens this folder, with no trust prompt, so here is
// everything this one does - nothing else. It makes no network calls itself (step 2 may, through your package
// manager):
//
//   1. Before each tool call it asks the guard core (.opencode/hooks/guard-core.cjs) two questions and blocks the
//      call by throwing when the answer is no: is this shell command a destructive git command (reset --hard,
//      checkout --, restore, clean), and is this edit aimed at a lock file or a .env file? If it cannot read the
//      request, it blocks, and if the guard core itself will not load (missing, or crashing as it loads), it blocks
//      every shell, edit, and patch call. opencode.json holds the same rules as a permission list; this adds what a
//      list of patterns cannot catch, like `bash -c "git reset --hard"` or an edit made through a patch.
//   2. When you open a session (not a subagent's) it runs .opencode/hooks/session-start.sh, which installs
//      dependencies if they are missing and runs `blit doctor`. Output is discarded and a failure never stops the
//      session.
//
// The "ask first" commands (force push, branch -D, stash drop) are left to the permission list in opencode.json,
// because a plugin can only block, not ask. When one is written in a way that list cannot see (an uppercase GIT, a
// quoted value, a tab, `bash -c "..."`), this blocks it instead and tells the assistant to ask you and then run it as
// a plain git command, which OpenCode does ask about. It checks this against a copy of the list written into this
// file, the same patterns as opencode.json.

import type { Plugin } from '@opencode-ai/plugin';

type GuardCore = typeof import('../hooks/guard-core.cjs');

/** Tools that write files. `apply_patch` and `patch` name their files inside the patch text instead of `filePath`. */
const EDIT_TOOLS = new Set(['edit', 'write', 'multiedit']);
const PATCH_TOOLS = new Set(['apply_patch', 'patch']);

/** The fields this guard reads. OpenCode types a tool call's arguments as `any`. */
interface ToolCallArgs {
    command?: unknown;
    filePath?: unknown;
    patchText?: unknown;
}

/** Every file a tool call would write, or throws when there is none to find (so the guard fails closed). */
function editedFiles({ patchPaths }: GuardCore, tool: string, args: ToolCallArgs): string[] {
    if (PATCH_TOOLS.has(tool)) {
        // The guard core reads the `*** Add File:` / `Update File:` / `Delete File:` / `Move to:` headers the way
        // OpenCode's own parser does (space after the colon optional, edges trimmed), and tolerates an indented header
        // OpenCode would not read, so it can only ever see more files than OpenCode does. A patch that is not
        // text names nothing, the same as one whose headers name no file.
        const files = typeof args.patchText === 'string' ? patchPaths(args.patchText) : [];

        if (files.length === 0) {
            throw new Error('the patch names no file');
        }

        return files;
    }

    if (typeof args.filePath !== 'string' || args.filePath === '') {
        throw new Error('the edit names no file');
    }

    return [args.filePath];
}

/** OpenCode's own glob match (`Wildcard.match`): `*` is anything, `?` one character, a trailing ` *` may match nothing. */
function globMatches(text: string, pattern: string): boolean {
    const source = pattern
        .split('*')
        .map((part) => part.replace(/[.+^${}()|[\]\\]/g, '\\$&').replaceAll('?', '.'))
        .join('.*')
        .replace(/ \.\*$/, '( .*)?');

    return new RegExp(`^${source}$`, 's').test(text);
}

/**
 * Whether OpenCode's permission list asks about (or denies) every part of this command the guard core objects to, as
 * written. Every part, not any: a part the user once approved "always" would otherwise carry an unseen one through.
 * OpenCode checks the text of each command its parser finds, including inside `(...)`, `$(...)` and backticks, but not
 * a declaration (`export X=...`), a bare assignment, a heredoc body, or a command spelled out in a string for another
 * program to run (`bash -c "..."`). This cuts the text at the same separators, never inside quotes or after a
 * backslash, so it can only find fewer commands than OpenCode does, never more.
 */
function asksFirst(core: GuardCore, command: string): boolean {
    if (command.includes('<<')) {
        return false;
    }

    // opencode.json's bash permission rules, written in when the kit generates this file. Parsed here, not at the top
    // of the file, so a broken copy blocks the call instead of stopping the plugin from loading. The rules spell option
    // prefixes git accepts (`--force` cut short), so a spellchecker skips the line.
    // cspell:disable-next-line
    const rules: Record<string, string> = JSON.parse('{"*GIT_CONFIG_KEY_*":"ask","*GIT_CONFIG_PARAMETERS*":"ask","*git *config *??????.*.???? ?*":"ask","*git *config *??????.*.????\' ?*":"ask","*git *config *??????.*.????\\" ?*":"ask","*git *config *??????.*.?????? ?*":"ask","*git *config *??????.*.??????\' ?*":"ask","*git *config *??????.*.??????\\" ?*":"ask","*git *config *--ren*":"ask","*git *config *rename-section*":"ask","git reset *--hard*":"deny","git reset *--h":"deny","git reset *--h *":"deny","git reset *--ha":"deny","git reset *--ha *":"deny","git reset *--har":"deny","git reset *--har *":"deny","git checkout -- *":"deny","git checkout * -- *":"deny","git checkout .":"deny","git checkout * .":"deny","git checkout -f*":"deny","git checkout * -f*":"deny","git checkout *--f*":"deny","git checkout -p*":"deny","git checkout * -p*":"deny","git checkout -2*":"deny","git checkout * -2*":"deny","git checkout -3*":"deny","git checkout * -3*":"deny","git checkout *--pat*":"deny","git checkout *--ou*":"deny","git checkout *--th*":"deny","git checkout *--no-over*":"deny","git switch -f*":"deny","git switch * -f*":"deny","git switch *--f":"deny","git switch *--f *":"deny","git switch *--fo":"deny","git switch *--fo *":"deny","git switch *--for":"deny","git switch *--for *":"deny","git switch *--forc":"deny","git switch *--forc *":"deny","git switch *--force":"deny","git switch *--force *":"deny","git switch *--di*":"deny","git restore *":"deny","git restore --staged *":"allow","git clean":"deny","git clean *":"deny","git clean -n*":"allow","git clean --dry-run*":"allow","git push -f*":"ask","git push * -f*":"ask","git push *--force*":"ask","git push * +*":"ask","git push -uf*":"ask","git push * -uf*":"ask","git push -vf*":"ask","git push * -vf*":"ask","git push -qf*":"ask","git push * -qf*":"ask","git push -nf*":"ask","git push * -nf*":"ask","git push -df*":"ask","git push * -df*":"ask","git push -4f*":"ask","git push * -4f*":"ask","git push -6f*":"ask","git push * -6f*":"ask","git branch -D *":"ask","git branch * -D*":"ask","git branch -df*":"ask","git branch * -df*":"ask","git branch -fd*":"ask","git branch * -fd*":"ask","git branch -d -f*":"ask","git branch * -d -f*":"ask","git branch -f -d*":"ask","git branch * -f -d*":"ask","git branch -d --force*":"ask","git branch * -d --force*":"ask","git branch --force -d*":"ask","git branch * --force -d*":"ask","git branch --delete -f*":"ask","git branch * --delete -f*":"ask","git branch -f --delete*":"ask","git branch * -f --delete*":"ask","git branch --delete --force*":"ask","git branch * --delete --force*":"ask","git branch --force --delete*":"ask","git branch * --force --delete*":"ask","git stash drop*":"ask","git stash clear*":"ask","git *-c alias.*":"deny","git *--config-env*alias.*":"deny","git *-c * push*":"ask","git *--config-env* push*":"ask","*git *config *alias.* ?*":"deny","*git *config *rename-section *alias*":"deny","*git *config *--ren* *alias*":"deny","*GIT_CONFIG_KEY_*=alias.*":"deny","*GIT_CONFIG_PARAMETERS=*alias.*":"deny","git checkout-index *":"deny","git read-tree *--res*":"deny","git push -d*":"ask","git push * -d*":"ask","git push *--de*":"ask","git push * :*":"ask","git push :*":"ask","git push *--mi*":"ask"}');

    // Same length as the command, with quoted spans and escaped characters blanked out.
    const masked = command.replace(/'[^']*'|"(?:[^"\\]|\\.)*"|\\[\s\S]/g, (span) => ' '.repeat(span.length));
    const pieces: string[] = [];
    let start = 0;

    for (const { index } of masked.matchAll(/[\n;&|()`]/g)) {
        pieces.push(command.slice(start, index).trim());
        start = index + 1;
    }

    pieces.push(command.slice(start).trim());

    const flagged = pieces.filter((piece) => core.isDangerousCommand(piece) !== null);

    return (
        flagged.length > 0 &&
        flagged.every((piece) => {
            if (/^(export|declare|typeset|local|readonly)(\s|$)|^(\w+=\S*(\s+|$))*$/.test(piece)) {
                return false;
            }

            // Last match wins, as in OpenCode; no match is allow.
            let verdict = 'allow';

            for (const [pattern, action] of Object.entries(rules)) {
                if (globMatches(piece, pattern)) {
                    verdict = action;
                }
            }

            return verdict !== 'allow';
        })
    );
}

/** The verdict for one tool call: null to allow it, otherwise something with a message. */
function classifyCall(core: GuardCore, tool: string, args: ToolCallArgs): { message: string } | null {
    if (tool === 'bash') {
        if (typeof args.command !== 'string') {
            throw new Error('the shell command is not text');
        }

        const verdict = core.isDangerousCommand(args.command);

        if (verdict?.decision === 'deny') {
            return { message: `${verdict.userMessage} ${verdict.agentMessage}` };
        }

        // An `ask` is the permission list's job, since a plugin can only block. Block only a form the list cannot see.
        if (verdict?.decision === 'ask' && !asksFirst(core, args.command)) {
            return {
                message: `${verdict.userMessage} ${verdict.agentMessage} OpenCode cannot ask about it written this way: once the user agrees, run it as a plain git command (lowercase git, no quotes or tabs, flags written separately) so OpenCode asks.`,
            };
        }

        return null;
    }

    if (EDIT_TOOLS.has(tool) || PATCH_TOOLS.has(tool)) {
        for (const file of editedFiles(core, tool, args)) {
            const verdict = core.isProtectedPath(file);

            if (verdict !== null) {
                return verdict;
            }
        }
    }

    return null;
}

export const KitGuard: Plugin = async ({ $, directory }) => {
    // Loaded here, not by a top-level import: OpenCode skips a plugin whose import throws and runs every call
    // unguarded. A string here is the reason it would not load.
    const core = await import('../hooks/guard-core.cjs').then(
        (module): GuardCore => module.default,
        (error: unknown) => (error instanceof Error ? error.message : String(error)),
    );

    return {
        'tool.execute.before': async (input, output) => {
            if (typeof core === 'string') {
                if (input.tool === 'bash' || EDIT_TOOLS.has(input.tool) || PATCH_TOOLS.has(input.tool)) {
                    throw new Error(`[BLOCKED] The guard could not run, so the request was blocked: ${core}`);
                }

                return;
            }

            const verdict = core.failClosed(() => classifyCall(core, input.tool, output.args));

            if (verdict !== null) {
                throw new Error(verdict.message);
            }
        },

        event: async ({ event }) => {
            // A subagent's session has a parent; only the session the person opened needs the bootstrap.
            if (event.type === 'session.created' && event.properties.info.parentID === undefined) {
                // Bun's shell types every variable as a string. An unset variable is not an own property of
                // `process.env`, so copying only strings keeps the script's environment. The install command
                // is set first so a variable of the same name already in the environment does not replace it.
                const env: Record<string, string> = { BLIT_PM_INSTALL: 'pnpm install' };

                for (const [key, value] of Object.entries(process.env)) {
                    if (value !== undefined && key !== 'BLIT_PM_INSTALL') {
                        env[key] = value;
                    }
                }

                await $`sh .opencode/hooks/session-start.sh`.cwd(directory).env(env).quiet().throws(false);
            }
        },
    };
};
